events.diff:
--- before/filter.mjs
+++ after/filter.mjs
@@ -1,5 +1,5 @@
 export class FilterService {
  constructor(store) { this.store = store; }
  save(user, name, values) { if (!user || !name) throw Error('name and owner required'); this.store.set(user, {name, values: structuredClone(values)}); }
- restore(user) { const entry = this.store.get(user); if (!entry) throw Error('no saved filter'); return {}; }
+ restore(user) { const entry = this.store.get(user); if (!entry) throw Error('no saved filter'); return structuredClone(entry.values); }
 }

